SELECT customers.customer_id, customers.first_name, customers.last_name, customers.email
FROM customers
WHERE NOT EXISTS (
  SELECT 1
  FROM orders
  WHERE orders.customer_id = customers.customer_id
);
ORDER BY customers.customer_id;
```

